98d924", "type": "concept", "title": "Ethical use of assumptions"}, {"id": "2c0b2360-4964-47cb-894f-cdab894f54e5", "type": "concept", "title": "Version control and accountability"}], "description": "Modelers are stewards of decisions and capital."}]}, {"id": "d2769fa0-b575-4122-8088-1d0520fa2eef", "type": "topic", "title": "Excel Fundamentals for Finance", "description": "This topic builds the fast, accurate spreadsheet mechanics needed for professional finance work.", "children": [{"id": "78d00b97-3981-4dbd-b030-4cae612592df", "type": "subtopic", "title": "Core spreadsheet fluency", "children": [{"id": "bf04dffb-a0f0-4631-9ed9-82c51503bee6", "type": "concept", "title": "Relative and absolute references"}, {"id": "5afcb36c-439a-4a9a-a86a-c1409490e132", "type": "concept", "title": "Lookup functions"}, {"id": "8bb38ce8-f6c0-46a2-b16e-8cb58af4d810", "type": "concept", "title": "Date, text, and error-handling functions"}], "description": "Students build speed and accuracy with formulas analysts use daily."}, {"id": "a6cd82be-6df0-40f1-a011-f54b3620c0b3", "type": "subtopic", "title": "Finance functions", "children": [{"id": "3c204ae6-995a-4c85-8242-456e647ed8da", "type": "concept", "title": "NPV, XNPV, IRR, and XIRR"}, {"id": "88eceaa1-71b7-4c3b-a7e8-95d613f42319", "type": "concept", "title": "PMT and debt amortization"}, {"id": "852a68f2-bf92-4594-9a86-3b9f86347fb4", "type": "concept", "title": "Goal Seek and basic Solver"}], "description": "Excel becomes useful when formulas connect directly to finance math."}, {"id": "b9a20a06-6be9-4038-a804-d6605af3564b", "type": "subtopic", "title": "Productivity and controls", "children": [{"id": "080fafa6-c939-415d-a0bd-4cd5c1cb889a", "type": "concept", "title": "Keyboard shortcuts"}, {"id": "886fa53f-fdc4-481b-9d99-2a635dcf5c38", "type": "concept", "title": "Named ranges and structured references"}, {"id": "df994a7f-e270-4268-920d-519cbc88120e", "type": "concept", "title": "Formula auditing tools"}], "description": "Professional speed comes from keyboard habits and controlled workflows."}]}, {"id": "b7ba2907-a798-4054-85e4-3b135f9b2406", "type": "topic", "title": "Model Architecture, Structure, and Auditability", "description": "Students learn to design models that are readable, traceable, flexible, and easy to review.", "children": [{"id": "e9d83b43-7fcc-4e4f-a0a4-a2f7e3ecd5d5", "type": "subtopic", "title": "Workbook design", "children": [{"id": "67c6e749-ac87-4717-9980-a5245d4e936b", "type": "concept", "title": "Inputs, calculations, outputs, and checks"}, {"id": "5b9af21c-5b3e-4384-af02-d372f230f54e", "type": "concept", "title": "Worksheet organization"}, {"id": "c25641b4-c1c6-4254-ade4-b904d5e26a41", "type": "concept", "title": "Consistent timeline and units"}], "description": "Structure determines whether a model can survive revisions and review."}, {"id": "12db751a-e61e-416b-a155-6427bfc7f95f", "type": "subtopic", "title": "Formatting conventions", "children": [{"id": "eb08ce58-a14c-4427-9d83-557d850b25a3", "type": "concept", "title": "Hardcodes, formulas, links, and outputs"}, {"id": "f701420f-b3e2-43d6-b9c2-e747b4fb5c81", "type": "concept", "title": "Color coding"}, {"id": "aa132648-f6ac-4111-a32c-9753d8563660", "type": "concept", "title": "Sign convention and units"}], "description": "Visual conventions reduce errors and make assumptions obvious."}, {"id": "776275f5-350e-4c16-b211-fca0543f0db3", "type": "subtopic", "title": "Audit trail", "children": [{"id": "565bdc3a-7ad8-4572-869c-bb4c7d87895a", "type": "concept", "title": "Source notes"}, {"id": "cf5deab3-bdc4-4b23-ace1-57e48a25259d", "type": "concept", "title": "Assumption logs"}, {"id": "b252e829-b12b-4ed9-9826-5f071e1dd283", "type": "concept", "title": "Version history"}], "description": "A robust model explains where numbers came from."}]}, {"id": "56497827-7ab5-463c-b0f8-24b3b5700da8", "type": "topic", "title": "Financial Statement Analysis and Source Data", "description": "Good models begin with reliable historical financials, accounting judgment, and clean source data.", "children": [{"id": "699f38a0-1785-4c2c-86f6-43d3ae76d8a6", "type": "subtopic", "title": "Historical statements", "children": [{"id": "dfbaecca-88fb-4f8f-9cb7-43940c5501f9", "type": "concept", "title": "Income statement, balance sheet, cash flow statement"}, {"id": "2a777fc3-a552-4af8-bede-d0e1f04be326", "type": "concept", "title": "10-K and 10-Q extraction"}, {"id": "f949b894-f2d6-471f-ae45-b28a8ff2e99f", "type": "concept", "title": "Fiscal calendars and restatements"}], "description": "Students learn to turn filings into clean model-ready data."}, {"id": "16fefb9f-8732-47f1-882a-37d1eeb4e103", "type": "subtopic", "title": "Accounting quality", "children": [{"id": "eb9d8daf-cc29-419a-ac04-b7652b299cc4", "type": "concept", "title": "Revenue recognition"}, {"id": "0cc26581-e844-4584-94ea-f7f9c9ef688c", "type": "concept", "title": "Working capital accounting"}, {"id": "94368674-4c77-499d-b8d6-65a84bf185ca", "type": "concept", "title": "Nonrecurring items and normalization"}], "description": "Forecasts are only as good as the accounting inputs beneath them."}, {"id": "8e63de68-395d-4adb-941e-7f84eadb6770", "type": "subtopic", "title": "Ratio and trend analysis", "children": [{"id": "7c070e2b-e367-4ac6-a436-2c6eb2d906d7", "type": "concept", "title": "Margins and turnover"}, {"id": "d4fb39cf-0feb-4383-b0ba-6e0f652242b2", "type": "concept", "title": "Liquidity and leverage"}, {"id": "df201eaa-87f7-4486-a548-40d27dac36f6", "type": "concept", "title": "Return on capital and growth quality"}], "description": "Historical patterns inform but do not mechanically determine forecasts."}]}, {"id": "e4f84896-3623-4326-8372-bd830ebf8cf8", "type": "topic", "title": "Operating Forecasts: Revenue, Margins, Working Capital, and Capex", "description": "Students translate business drivers into forecast assumptions that connect to economic reality.", "children": [{"id": "43c17ac6-2035-42bd-b325-d41fd1c65418", "type": "subtopic", "title": "Revenue drivers", "children": [{"id": "6d54e970-f320-43a1-be8a-d9273e5fb2cd", "type": "concept", "title": "Volume and pricing"}, {"id": "2b839e09-66ab-4e30-b9bf-fd07f2611396", "type": "concept", "title": "Segment-level forecasts"}, {"id": "d6d1c71f-37cc-4bf8-8ac1-6b131a9a8f50", "type": "concept", "title": "Market share and total addressable market"}], "description": "Students connect revenue forecasts to customers, price, volume, and market structure."}, {"id": "8802c699-4261-4cce-9f94-c9e6904c6d72", "type": "subtopic", "title": "Expense and margin modeling", "children": [{"id": "1aea5bf6-fc98-48ea-b368-843def3a6727", "type": "concept", "title": "COGS and gross margin"}, {"id": "1d3d932d-45de-4db2-a118-38295c2ef80e", "type": "concept", "title": "SG&A, R&D, and operating leverage"}, {"id": "692b29de-76b0-4828-a083-82383df407b7", "type": "concept", "title": "Fixed versus variable costs"}], "description": "Margins reflect operating leverage, input costs, and strategic choices."}, {"id": "b4f72cac-a737-45f0-8c1e-bad13ecb54a0", "type": "subtopic", "title": "Investment and working capital", "children": [{"id": "db1f6285-e4fd-4e84-a209-f3d153d4a7d3", "type": "concept", "title": "Accounts receivable, inventory, and payables"}, {"id": "ba44b8e3-2553-4b68-82f9-c5bf213d9474", "type": "concept", "title": "Capital expenditures"}, {"id": "9f295be3-150c-49fa-a724-d0721fd11f6b", "type": "concept", "title": "Depreciation and amortization"}], "description": "Growth consumes or releases cash through operations and reinvestment."}]}, {"id": "3b082249-b0b2-40fa-88ab-7bb9b354e054", "type": "topic", "title": "Three-Statement Integrated Model", "description": "This core module links the income statement, balance sheet, and cash flow statement into one coherent forecast.", "children": [{"id": "0f747950-50da-4653-b978-a8c768f752c0", "type": "subtopic", "title": "Income statement forecast", "children": [{"id": "8fdac69e-6b2d-4abe-8b78-60b1c82eac49", "type": "concept", "title": "Revenue build"}, {"id": "e8357d45-ee68-4c38-93c8-4114fabd1c18", "type": "concept", "title": "Operating expenses"}, {"id": "8680921d-6061-4067-99cc-eaeb6d11ad57", "type": "concept", "title": "Taxes and net income"}], "description": "Students model profitability from revenue through net income."}, {"id": "055511d4-653a-4aaf-a256-d690ed024165", "type": "subtopic", "title": "Balance sheet forecast", "children": [{"id": "3a8ec242-549f-4b77-829d-10e446c1ab37", "type": "concept", "title": "Working capital schedules"}, {"id": "c3b49bab-9426-41ab-8e28-7fad3ffc6a10", "type": "concept", "title": "PP&E roll-forward"}, {"id": "a6fa3954-9350-48da-8f66-bf6aaa149fe4", "type": "concept", "title": "Debt and equity accounts"}], "description": "The balance sheet checks whether the forecasted business remains financially coherent."}, {"id": "2c30b7c7-d8bf-49a8-a5a2-b5984c1c6034", "type": "subtopic", "title": "Cash flow integration", "children": [{"id": "3a30a6fc-cbea-4cfa-90cc-c39231988a7c", "type": "concept", "title": "Operating, investing, and financing cash flows"}, {"id": "fae9c111-e369-44e9-be76-92641b8c75d1", "type": "concept", "title": "Circularity and balancing"}, {"id": "dd846667-921a-4b16-92ac-189a9fa1aa16", "type": "concept", "title": "Balance-sheet integrity checks"}], "description": "Cash flow converts accrual earnings into funding needs and valuation inputs."}]}, {"id": "3d1fba45-7088-43b6-a2d5-1a64c45357d8", "type": "topic", "title": "Debt Schedules, Interest Expense, and Cash Sweep Mechanics", "description": "Students model financing structure, borrowing capacity, repayment, and covenant-relevant cash flow.", "children": [{"id": "9b8a7c73-bc0c-4ee3-bfe1-3235b8cd987a", "type": "subtopic", "title": "Debt instruments", "children": [{"id": "26eb5a2b-7718-4387-a490-63360507b382", "type": "concept", "title": "Revolvers"}, {"id": "eff2ff87-1467-482b-b52a-374828da2f38", "type": "concept", "title": "Term loans and bonds"}, {"id": "63fd2c71-1317-49e7-9e77-1241b32d18a5", "type": "concept", "title": "PIK and amortizing debt"}], "description": "Students learn how different debt types behave in a model."}, {"id": "ceee1885-4544-4349-8ec5-2905ee07889a", "type": "subtopic", "title": "Interest and repayment", "children": [{"id": "27ada5cf-e0a6-48a1-a9cc-281dbf0ff35c", "type": "concept", "title": "Average debt balances"}, {"id": "fd79412c-2369-4620-8df5-97837e97de21", "type": "concept", "title": "Cash sweep logic"}, {"id": "7d88913a-728c-4063-8de8-00db9ea5cc6d", "type": "concept", "title": "Mandatory and optional amortization"}], "description": "Debt schedules connect leverage to cash flow and earnings."}, {"id": "74be7373-df6a-4bc8-bc63-8c6fd81c8120", "type": "subtopic", "title": "Credit constraints", "children": [{"id": "dc133a6b-d9ca-41f2-bf76-16aaa0e3a1eb", "type": "concept", "title": "Leverage and coverage ratios"}, {"id": "a0ea73be-234c-4084-bad7-bd43bd9a9e4d", "type": "concept", "title": "Covenants"}, {"id": "480a204d-1f31-4ce5-a359-862fb7cc161b", "type": "concept", "title": "Borrowing capacity"}], "description": "Models must respect lender economics and covenants."}]}, {"id": "327c07b2-04c1-4a28-a4b5-67d42192a795", "type": "topic", "title": "Discounted Cash Flow Valuation", "description": "DCF modeling connects operating forecasts to intrinsic enterprise and equity value.", "children": [{"id": "b0743fc1-c37b-4d3b-bf5f-641c8974c4da", "type": "subtopic", "title": "Free cash flow", "children": [{"id": "b9c179b3-310c-4b33-99a5-dc7268aa64d3", "type": "concept", "title": "FCFF and FCFE"}, {"id": "b8671d34-6bb1-4550-acb6-a37f24d787ce", "type": "concept", "title": "NOPAT and reinvestment"}, {"id": "e7b2dd53-b612-45fb-a619-cce1903768ee", "type": "concept", "title": "Working capital and capex assumptions"}], "description": "DCF starts by translating operations into cash available to capital providers."}, {"id": "a2c5e148-0e1a-49e4-adf5-5f3df076a3ad", "type": "subtopic", "title": "Discount rates", "children": [{"id": "5128e5bf-21ff-4caa-a5bc-ba5f7465cf9b", "type": "concept", "title": "WACC"}, {"id": "a3df5389-d125-4f5c-b62d-b38838fb69f0", "type": "concept", "title": "Cost of equity and beta"}, {"id": "b0aa5ff9-7a49-4d2c-a25d-dbed92229541", "type": "concept", "title": "Cost of debt and tax shields"}], "description": "Students estimate risk-adjusted required returns."}, {"id": "ede5d8d3-1e7e-49b9-ac88-b1c874a1e96b", "type": "subtopic", "title": "Terminal value and equity bridge", "children": [{"id": "d890a436-2b53-4fc3-8e87-7dfba519ce5f", "type": "concept", "title": "Perpetuity growth"}, {"id": "33747276-6da5-4355-bbd3-bdd7d05c0062", "type": "concept", "title": "Exit multiple method"}, {"id": "2725273e-2abc-44ea-90e5-6b024c0e2299", "type": "concept", "title": "Enterprise value to equity value"}], "description": "Most DCF value rests in terminal assumptions, so they deserve scrutiny."}]}, {"id": "1623c27a-8ac9-48ed-988e-a132954ed4ff", "type": "topic", "title": "Trading Comparables and Precedent Transactions", "description": "Students learn market-based valuation using peer companies and transaction evidence.", "children": [{"id": "8cc52b50-a49f-4aba-b65c-9fafc2147de7", "type": "subtopic", "title": "Comparable company analysis", "children": [{"id": "d6e64028-a24b-44d3-94b5-70111c18f608", "type": "concept", "title": "Peer selection"}, {"id": "8601b5d1-cbb9-4e3b-aa84-04d3cebfd814", "type": "concept", "title": "EV/Revenue, EV/EBITDA, P/E"}, {"id": "0a24c8e0-008a-4892-a0e1-ebad26541957", "type": "concept", "title": "Calendarization and normalization"}], "description": "Public peers provide market evidence for valuation ranges."}, {"id": "05e97dee-f605-4d79-9f6b-8e7f492d7c7c", "type": "subtopic", "title": "Precedent transactions", "children": [{"id": "f566b11a-3702-4a6b-a16c-9ba498b6ad7c", "type": "concept", "title": "Transaction screening"}, {"id": "d59cb9f7-8a06-4cc2-bbb6-876fa74fa301", "type": "concept", "title": "Control premiums"}, {"id": "fdda8ad9-8dd8-41c6-a451-5484523f63f4", "type": "concept", "title": "Synergy and cycle effects"}], "description": "Deal data show what buyers paid under specific conditions."}, {"id": "7cd4fa77-f1c2-4fe4-b8ee-d5048be27321", "type": "subtopic", "title": "Valuation synthesis", "children": [{"id": "3d21deba-a14c-4f97-b2d1-a4fddf52fa38", "type": "concept", "title": "Football fields"}, {"id": "80c8191c-2e75-440d-b517-a86fc1c72c38", "type": "concept", "title": "Range selection"}, {"id": "fff9eca3-4521-471b-a134-9f1d795a53d5", "type": "concept", "title": "Outlier handling"}], "description": "Students learn to reconcile evidence rather than report false precision."}]}, {"id": "271553f4-aaac-4395-98e9-fde3038e3254", "type": "topic", "title": "Leveraged Buyout Modeling", "description": "This module teaches returns analysis under debt financing, sponsor economics, and exit assumptions.", "children": [{"id": "dba85f56-45f1-4470-a597-c2c00a8d9587", "type": "subtopic", "title": "LBO mechanics", "children": [{"id": "b07ef989-b185-4321-960d-25f1ac12bf70", "type": "concept", "title": "Sources and uses"}, {"id": "b43324de-f2e5-4297-b034-490f5fa46995", "type": "concept", "title": "Purchase price and leverage"}, {"id": "d5582189-dbb5-4ce8-8dab-43c9e7cc2088", "type": "concept", "title": "Management rollover and fees"}], "description": "An LBO model tests whether cash flows can support debt and generate sponsor returns."}, {"id": "0aef0a53-731b-46d5-bd22-6e13fcad99bb", "type": "subtopic", "title": "Returns analysis", "children": [{"id": "7d50be72-bc2f-423d-9bc5-665993ea1578", "type": "concept", "title": "IRR and MOIC"}, {"id": "534bb0db-01ee-408e-96cd-92872f4ed146", "type": "concept", "title": "Exit multiple"}, {"id": "72b15372-fb58-4126-8c91-f244d52f8c84", "type": "concept", "title": "Debt paydown"}], "description": "Students connect operating performance, deleveraging, and exit value to investor returns."}, {"id": "1c622108-68f3-42d3-bb78-0de8ed23d472", "type": "subtopic", "title": "LBO risk", "children": [{"id": "e5c9d921-87cf-4676-9055-60f30b903d7b", "type": "concept", "title": "Downside cases"}, {"id": "0307cad1-e2d2-45e8-9111-cc53db8b8a1c", "type": "concept", "title": "Covenant pressure"}, {"id": "dedbb4da-d7cd-40d3-844e-038b98eac864", "type": "concept", "title": "Refinancing and exit risk"}], "description": "High leverage makes assumptions fragile."}]}, {"id": "eb76d0f8-c5e5-4f5b-95ae-d68de616a199", "type": "topic", "title": "Merger and Acquisition Modeling", "description": "Students model transaction structure, purchase accounting, synergies, accretion/dilution, and deal returns.", "children": [{"id": "7f4baa3a-39d1-41b2-94af-ec5528f9a78c", "type": "subtopic", "title": "Deal structure", "children": [{"id": "4740a551-9a4e-4204-9bc8-6231968bc6e7", "type": "concept", "title": "Cash, stock, and mixed consideration"}, {"id": "f4591348-2829-42cd-b7af-3c96630862cf", "type": "concept", "title": "Offer premium"}, {"id": "0e370e50-9fde-49ec-836f-9543cef40659", "type": "concept", "title": "Sources and uses"}], "description": "Students model how buyers pay and how consideration affects ownership and returns."}, {"id": "978ddc85-209c-4909-863a-ec49027e9799", "type": "subtopic", "title": "Purchase accounting", "children": [{"id": "4c542bc1-c0c2-4363-bff3-32e664a32e61", "type": "concept", "title": "Goodwill and intangibles"}, {"id": "1e465011-cff5-4e35-9365-a0580e8f715b", "type": "concept", "title": "Purchase price allocation"}, {"id": "6be02d67-7d70-4342-a87d-56a0c5a780fd", "type": "concept", "title": "Pro forma balance sheet"}], "description": "M&A models require accounting for acquired assets and financing."}, {"id": "83815770-4ce9-456b-a23e-dcc7f86e7cd0", "type": "subtopic", "title": "Accretion/dilution and synergies", "children": [{"id": "72d2478c-5bbd-4ea9-8c1a-fd9ece3399a8", "type": "concept", "title": "EPS accretion/dilution"}, {"id": "e4248371-8e62-497e-9620-8e4335d4be41", "type": "concept", "title": "Revenue and cost synergies"}, {"id": "dd66e20f-ff4f-4b52-aa9a-714c01435619", "type": "concept", "title": "Integration costs"}], "description": "Students test whether a deal improves per-share economics and strategic value."}]}, {"id": "d0bb1adf-bb93-4b2f-8449-d522928982ff", "type": "topic", "title": "Scenario, Sensitivity, Data Table, and Monte Carlo Analysis", "description": "Professional modeling treats uncertainty explicitly through scenarios, sensitivities, and simulation.", "children": [{"id": "568f7019-98fc-42cd-927d-4eea89455c87", "type": "subtopic", "title": "Scenario design", "children": [{"id": "bb00e7e2-d6fa-4c98-8220-065fb538e20e", "type": "concept", "title": "Base, upside, downside"}, {"id": "6f2dfc26-f7f8-43ec-89f8-dd1958b9b384", "type": "concept", "title": "Macroeconomic and operating cases"}, {"id": "f84341ac-0724-4041-b683-f04f6073a370", "type": "concept", "title": "Management cases versus analyst cases"}], "description": "Scenarios should tell coherent business stories, not random collections of assumptions."}, {"id": "a2fb91d7-acce-44b6-8965-f63252d9fa46", "type": "subtopic", "title": "Sensitivity analysis", "children": [{"id": "0fb51c84-3466-4f3b-b0da-393ec2e8f210", "type": "concept", "title": "One-way and two-way data tables"}, {"id": "cf87606e-0cf9-4cad-89cf-9c243b23a561", "type": "concept", "title": "Tornado charts"}, {"id": "e9fc09cb-95a2-4de1-b5cb-9e0451eea58d", "type": "concept", "title": "Breakeven analysis"}], "description": "Sensitivity tables reveal which assumptions matter most."}, {"id": "72fee162-af68-409f-9964-006dd7c47bc1", "type": "subtopic", "title": "Simulation", "children": [{"id": "1bf8a660-1ad3-4fc6-a891-703580225480", "type": "concept", "title": "Input distributions"}, {"id": "809f5948-9940-42ec-9a33-2dd62471cbe2", "type": "concept", "title": "Correlation assumptions"}, {"id": "97b44bf2-be84-49ab-81d6-1f48431b27fc", "type": "concept", "title": "Output percentiles and risk ranges"}], "description": "Monte Carlo methods model distributions rather than single cases."}]}, {"id": "6dddff14-4de7-4d38-8b7d-6e2e08418f17", "type": "topic", "title": "Optimization and So